
import streamlit as st
import pandas as pd
import plotly.express as px

st.set_page_config(layout= 'wide', page_title= 'Car Insurance EDA')

html_title = "<h1 style=color:white;text-align:center;> Car Insurance EDA Project </h1>"
st.markdown(html_title, unsafe_allow_html= True)

st.image('https://prod.cosy.bmw.cloud/bmwweb/cosySec?COSY-EU-100-2545xM4RIyFnbm9Mb3AgyyIJrjG0suyJRBODlsrjGpuaprQbhSIqppglBgMxEJl384MlficYiGHqoQxYLW7%25f3tiJ0PCJirQbLDWcQW7%251uNRrqoQh47wMvcYi9t5BJMb3islBglUUJecRScH8R4MbnMdoPeyJGy53LvrQ%25r9YaJW8zWuEJQqogqaFQ7l3ilUjzJcRScH78lMbnMd0zqyJGy5iubrQ%25r9SbUW8zWunDjqogqaG4zl3ilU%25QocRScHzUVMbnMdg4ayJGy5iJUrQ%25r9saYW8zWuKbGqogqaDJKl3ilUCQIcRScH4%25bMbnMdJmSyJGy5Q3SrQ%25r98R5W8zWuobuqogqa3Jnl3ilUR%25gcRScHbU8MbnMdJbkyJGy5Q4ErQ%25r993UW8zWuu3HqogqaaUbl3ilUjv0cRSrQdr9SMBW8zcRacHHwsMbnW85WuEfuqoQEdcNq0zxcqW8JuzM8nq0z6Fboy6oEd82')

page = st.sidebar.radio('Page', ['Home', 'Univariate', 'Multivariate'])

df = pd.read_csv('cleaned_df.csv', index_col= 0)

if page == 'Home':

    st.header('Dataset Overview')
    st.dataframe(df)

    st.header('Dataset Description')
    st.image('data:image/png;base64,')

elif page == 'Univariate':
    
    tab_num, tab_cat = st.tabs(['Numerical', 'Categorical'])

    # Numerical Tab
    num_cols = df.select_dtypes(include= 'number').columns.drop('claim_flag')
    column_num = tab_num.selectbox('Column', num_cols)
    tab_num.plotly_chart(px.histogram(data_frame= df, x= column_num, title= column_num))

    # Categorical Tab
    cat_cols = df.select_dtypes(include= 'object').columns.to_list() + ['claim_flag']
    column_cat = tab_cat.selectbox('Column', cat_cols)

    chart = tab_cat.selectbox('Chart', ['Histogram', 'Pie'])

    if chart == 'Histogram':
        tab_cat.plotly_chart(px.histogram(data_frame= df, x= column_cat, title= column_cat).update_xaxes(categoryorder = 'max descending'))

    elif chart == 'Pie':
        tab_cat.plotly_chart(px.pie(data_frame= df, names= column_cat, title= column_cat))

elif page == 'Multivariate':

    st.header('Is there any numerical correlation between Data ?')
    corr_df = df.corr(numeric_only= True).round(2).drop('claim_flag', axis= 1)
    st.plotly_chart(px.imshow(corr_df, text_auto= True, width= 1000, height= 800))

    st.header('What is the average Income per Claim Flag ?')
    claim_income_df = df.groupby('claim_flag')['income'].mean().round(2).reset_index()
    st.plotly_chart(px.bar(data_frame= claim_income_df, x= 'claim_flag', y= 'income', labels= {'claim_flag' : 'Claim Flag', 'income' : 'Average Income'}, text_auto= True))

    st.header('Which gender makes more claims ?')
    st.plotly_chart(px.histogram(data_frame= df, x= 'gender', color= 'claim_flag', barmode= 'group'))

    st.header('Does education level affect claim submission ?')
    st.plotly_chart(px.histogram(data_frame= df, x= 'education', color= 'claim_flag', barmode= 'group').update_xaxes(categoryorder = 'max descending'))
